func PlayAnimation() {
	var esc = "\x1b"
	for i := 0; i < len(frames); i++ {
		if i > 0 {
			fmt.Printf(esc+"[%dA", 20)
		}
		coreutils.PrintMessage(frames[i])
		// TODO: maybe it'll be better to use tickers instead of sleep
		time.Sleep(100 * time.Millisecond)
	}

	time.Sleep(3 * time.Second)
	fmt.Printf(esc+"[%dA", 20)
	fmt.Printf(esc + "[0J")
}
